const m=$json; const scenes=m.scenes||[]; const KEY=$vars.OPENAI_API_KEY; const voice=$vars.OPENAI_TTS_VOICE||'onyx'; const dir='/tmp/'+m.job+'_hf'; const b64=(s)=>Buffer.from(String(s||''),'utf8').toString('base64');
let t=0; const segs=scenes.map((s,i)=>{ const words=String(s.narration||'').split(/\s+/).filter(Boolean).length; const dur=Math.max(2.5, Math.round((words/2.6)*10)/10); const seg={ idx:i, start:Math.round(t*10)/10, dur, narration:s.narration||m.topic, cap:String(s.on_screen_text||'').replace(/</g,''), image_url:s.image_url||'', clip_url:s.clip_url||'' }; t+=dur; return seg; });
